#!/usr/bin/env python3
import subprocess
import sys

def main():
    cert_path = "/app/ssl/server.crt"

    # Check if certificate exists
    try:
        with open(cert_path, 'r') as f:
            content = f.read()
        if '-----BEGIN CERTIFICATE-----' not in content:
            print("Error: Certificate file does not contain valid certificate")
            sys.exit(1)
    except FileNotFoundError:
        print("Error: Certificate file not found")
        sys.exit(1)

    # Get certificate details using openssl
    try:
        result = subprocess.run(
            ['openssl', 'x509', '-in', cert_path, '-noout', '-subject', '-enddate'],
            capture_output=True, text=True, check=True
        )
        output = result.stdout
    except subprocess.CalledProcessError as e:
        print(f"Error: Failed to read certificate: {e}")
        sys.exit(1)

    # Parse subject to get Common Name
    subject_line = [line for line in output.split('\n') if 'subject' in line.lower()][0]
    cn = ""
    for part in subject_line.split(','):
        if 'CN' in part:
            cn = part.split('=')[1].strip()
            break

    # Parse end date to get expiration date in YYYY-MM-DD format
    end_line = [line for line in output.split('\n') if 'notAfter' in line.lower()][0]
    # Format: notAfter=Oct 14 20:08:28 2027 GMT
    date_str = end_line.split('=')[1].strip()
    # Extract YYYY-MM-DD
    import re
    match = re.search(r'(\d{4})-(\d{2})-(\d{2})', date_str)
    if match:
        exp_date = f"{match.group(1)}-{match.group(2)}-{match.group(3)}"
    else:
        # Try alternative format
        parts = date_str.split()
        if len(parts) >= 3:
            year = parts[-2]
            month = parts[-1].split()[0] if 'GMT' in parts[-1] else parts[-1]
            day = parts[-3]
            exp_date = f"{year}-{month}-{day}"
        else:
            exp_date = date_str

    print(f"Common Name: {cn}")
    print(f"Expiration Date: {exp_date}")
    print("Certificate verification successful")

if __name__ == "__main__":
    main()
